ALTER TABLE public.books ADD COLUMN cover_path text;
CREATE POLICY "Book covers readable by signed in users" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'book-covers');
CREATE POLICY "Assigned educators upload book covers" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'book-covers' AND owner_id = auth.uid()::text AND EXISTS (SELECT 1 FROM public.books b WHERE b.id::text = (storage.foldername(name))[1] AND (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'owner') OR (public.has_role(auth.uid(), 'teacher') AND public.teacher_has_course_access(auth.uid(), b.course_id)))));
CREATE POLICY "Assigned educators delete book covers" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'book-covers' AND EXISTS (SELECT 1 FROM public.books b WHERE b.id::text = (storage.foldername(name))[1] AND (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'owner') OR (public.has_role(auth.uid(), 'teacher') AND public.teacher_has_course_access(auth.uid(), b.course_id)))));